  'v2.fest.walksNone': '« My lantern walks behind nobody tonight. {unless} »',
  'v2.fest.wren': '« The custom of the Cité, friend: on the eve of the final the whole town carries lanterns behind the fighter it honours. The longest cortege opens the parade at dusk and takes the Lanterns\' Purse, {purse} coins, and a verse in my song. Ask around who walks behind whom. »',
  'v2.fest.rivalCount': '« {n} lanterns behind me tonight, last I counted. Carry yours where you like. »',
  'v2.fest.rivalAlone': '« Lanterns. In the north we light fires and fight by them. Count mine if you like: {n}. »',
  'v2.fest.rivalGift': '« You walk in my cortege tonight, {name}? I will not forget it. »',
  'v2.fest.deed.hang': 'Hang the hall\'s lanterns with Kell Barrow (+{n} behind you tonight)',
  'v2.fest.deed.flame': 'Carry Brother Ambrose\'s flame round the square (+{n} behind you tonight)',
  'v2.fest.deed.round': 'Stand a round at Lio\'s for the festival (+{n} behind you tonight)',
  'v2.fest.deedLog.hang': 'You hang the hall\'s lanterns with Kell Barrow all morning. The porters will carry {n} of them behind you tonight.',
  'v2.fest.deedLog.flame': 'You carry Brother Ambrose\'s flame from the shrine to the hall: {n} more lanterns behind you tonight.',
  'v2.fest.deedLog.round': 'You stand the house a round at Lio\'s: {n} more lanterns behind you tonight.',
  'v2.fest.notToday': 'Only on the festival\'s day, before the parade.',
  'v2.fest.notNow': 'Not at this hour of the festival.',
