  'v2.fest.poor': 'A round costs {n} coins.',
  'v2.fest.behindLabel': 'Walk in {name}\'s cortege tonight (your lanterns join theirs; no purse for you)',
  'v2.fest.ownLabel': 'Tell {name} you will lead your own cortege after all',
  'v2.fest.notHim': 'House Dree\'s cortege takes no lantern it has not paid for.',
  'v2.fest.already': 'You already walk in that cortege.',
  'v2.fest.own': 'You do not walk in that cortege.',
  'v2.fest.behindLog': 'You tell {name} you will walk in their cortege tonight: {n} lanterns behind them now.',
  'v2.fest.ownLog': 'You take your lanterns back: you lead your own cortege tonight.',
  'v2.fest.lead.you': 'Dusk on the festival square: {n} lanterns behind you, the longest cortege. You open the Lanterns\' parade, and the registrar hands you the Lanterns\' Purse, {purse} coins.',
  'v2.fest.lead.gift': 'Dusk on the festival square: {name} opens the Lanterns\' parade with {n} lanterns, yours among them.',
  'v2.fest.lead.rival': 'Dusk on the festival square: {name} opens the Lanterns\' parade with {n} lanterns.',
  'v2.fest.gift': '{name} will not forget who walked in their cortege tonight, and the town saw it.',
  'v2.fest.shutTag': 'The parade fills the way to {place}',
  'v2.fest.wayShut': 'The parade fills the street to the forecourt tonight: nobody passes until it has gone by.',
  'v2.fest.rule': 'Day 9, the Lanterns\' parade: each fighter leads a cortege, and every lantern walks behind the fighter its bearer honours - the crowd by renown, the town\'s people each for a reason they say. At dusk the longest cortege opens the parade and takes the Lanterns\' Purse: {purse} coins, {rep} reputation, {fame} fame. Equal, the greater renown leads.',
  'v2.fest.board.tonight': 'Tonight\'s parade: {n} lanterns. {list}.',
  'v2.fest.board.person': '{name}: « {why} »',
  'v2.fest.board.group': '{n} {why}',
  'v2.fest.board.none': 'Tonight\'s parade: no lantern behind {name} yet.',
  'v2.fest.board.behind': 'Walks in {name}\'s cortege tonight, the lanterns with theirs.',
  'v2.fest.board.led': 'Opened the Lanterns\' parade, {n} lanterns behind.',
  'v2.fest.board.walked': 'Walked in the Lanterns\' parade, {n} lanterns behind.',
  'v2.fest.board.gave': 'Walked in {name}\'s cortege at the Lanterns\' parade.',
  'v2.scene.eve.2out': '« Not my name this year. Tomorrow I shout from the stands with everyone else. »',
  'v2.scene.eve.call': '« The Lanterns\' parade! At its head, under the hall\'s crowns, {first}, with {n} lanterns! Then {second}, then {third}, and the whole Cité behind! »',
  'v2.scene.eve.verse': '« A verse, then, for {name}, who led the lanterns on the eve of the final: the Lanterns\' Purse, {purse} coins, and a line in my song for ever. »',
  'v2.scene.eve.gift': '« And sing for {name}, who carried their lanterns behind {rival} tonight: a verse for both of them! »',
  'v2.scene.epilogue.wren': '« And my song keeps its verse of the eve: {name}, who led the lanterns through the Cité. »',
  'v2.scene.epilogue.wren.crowned': '« The verse of the eve was right: {name} led the lanterns, and now wears the crown. Sing it, Cité! »',
